syntax = "proto2";
package Game;
enum Command
{
    cmd_place_holder = 0;
    S2C_LoginError = 0x1005; //登录错误
    S2C_LoginSucc = 0x1007; //登录房间成功 通知自己
    S2C_LogoutSucc = 0x1008; //退出房间成功 通知自己
    S2C_ReconnSucc = 0x1009; //重连成功
    S2C_UserEnterRoom = 0x100D; //玩家进入房间 通知其他玩家
    S2C_UserQuitRoom = 0x100E; //玩家退出房间
    S2C_UserReadyStatus = 0x4001; //玩家准备状态
    S2C_UserAutoStatus = 0x4007; //玩家托管状态
    S2C_UserWatchStatus = 0x4008; //玩家旁观状态
    
    S2C_SystemError = 0x5000;
    S2C_GameStart = 0x5001; //游戏开始
    S2C_DealCard = 0x5002; //发牌
    S2C_RoundStart = 0x5003; //回合开始
    S2C_RoundEnd = 0x5004; //回合结束
    S2C_StartPick = 0x5005; //玩家开始选牌
    C2S_PickCard = 0x5006; //提交选牌
    S2C_PickCard = 0x5007; //选牌结果

    S2C_Settle = 0x5012; //结算消息
    S2C_GameOver = 0x5017; //游戏结束
};

// S2C_LoginError
message RspLoginError 
{
    optional uint32 errcode = 1;
};

message RoomInfo 
{
    optional uint32 level = 1;
    optional uint32 basechip = 2;
    optional uint32 deskfee = 3;
    optional uint32 total_game = 4;
};

message RoomUserInfo 
{
    optional uint32 uid = 1;
    optional uint32 seatid = 2;
    optional bool ready = 3;
    optional bool ai = 4; //是否托管
    optional int64 money = 5;
    optional string userinfo = 6; //json格式
    optional bool watch = 7; //是否旁观
};

// S2C_LoginSucc
message RspLoginSuccess
{
    optional RoomInfo room_info = 1;
    optional RoomUserInfo self_info = 2;
    repeated RoomUserInfo others = 3;
};

// S2C_LogoutSucc
message RspLogoutSuccess 
{
    optional uint32 uid = 1; //退出玩家uid
};

// S2C_ReconnSucc
message RspReconnSuccess
{
    optional uint32 uid = 1; //自己uid
    optional uint32 optime = 2; //剩余操作时间
    optional RoomInfo room_info = 3;  
    repeated RoomUserInfo user_info = 4;
    optional uint32 round = 5;

    optional uint32 op_uid = 6; //正在出牌玩家
    optional RspDealCard handcards = 7; //玩家手牌信息
    optional uint32 table_score = 8;
    repeated PairItem user_score = 9; //玩家抓分
    repeated RspPickCard outcard_records = 10; //最近一圈出牌记录
};

// S2C_UserEnterRoom
message RspUserEnterRoom 
{
    optional RoomUserInfo userinfo = 1;
};

// S2C_UserQuitRoom
message RspUserQuitRoom
{
    optional uint32 uid = 1;
};

// S2C_UserReadyStatus
message RspUserReadyStatus
{
    optional uint32 uid = 1;
    optional bool ready = 2; // 0-未准备 1-准备 
};

// S2C_UserAutoStatus
message RspUserAutoStatus
{
    optional uint32 uid = 1;
    optional bool ai = 2; //0-未托管 1-托管
};

// S2C_UserWatchStatus
message RspUserWatchStatus {
    optional uint32 uid = 1;
    optional bool watch = 2; //1-旁观 0-非旁观
}

/////////////////////////////////////////////////////////////////////////

//对局出现异常，对局会结束
message SystemError 
{
    optional uint32 errcode = 1;
    optional string reason = 2;
};

// S2C_GameStart
message RspGameStart
{
    optional uint32 param = 1;
    optional uint32 type = 2;
}

message UserCards 
{
    optional uint32 uid = 1;
    repeated uint32 cards = 2;
    optional uint32 num = 3; //发牌后手牌数量
}

//S2C_DealCard
message RspDealCard 
{
    repeated UserCards cards = 1;
    optional uint32 left_num = 2; //牌堆剩余数量
    optional uint32 round = 3;
};

// S2C_RoundStart
message RspRoundStart 
{
    optional uint32 round = 1;
}

// S2C_RoundEnd
message RspRoundEnd 
{
    optional uint32 round = 1;
    optional uint32 round_score = 2; //桌面分
    optional uint32 winner = 3; //赢家uid
}

// S2C_StartPick
message RspStartPick
{
    optional uint32 round = 1;
    optional uint32 uid = 2;
    optional uint32 optime = 3;
}

//一组牌
message CardGroup
{
    optional uint32 type = 1;   // 牌型
    repeated uint32 cards = 2;
}

// C2S_PickCard 提交选牌
message ReqPickCard 
{
    optional bool pass = 1;
    optional CardGroup pick = 2;
}

// S2C_PickCard 选牌结果
message RspPickCard
{
    optional int32 errcode = 1; //非0提交有错误, 参考错误码
    optional uint32 uid = 2;
    optional bool pass = 3;
    optional CardGroup pick = 4; // 玩家选牌
    optional uint32 score = 5; // 桌面分
    optional uint32 round = 6; 
}

message PairItem 
{
    optional uint32 uid = 1;
    optional int64 value = 2;
}

message SettleItem 
{
    optional uint32 uid = 1;
    optional int32 score = 2;
    optional int64 turn_money = 3;
    repeated uint32 cards = 4; //玩家摊开手牌
}

// S2C_Settle 结算消息
message RspSettle 
{
    repeated SettleItem settle = 1;
}

// S2C_GameOver
message RspGameOver 
{
    optional uint32 param = 1;
};
